const body = $input.item.json.body || $input.item.json;
const leadId = body.lead_id || 'LEAD-001';
const followUp = body.follow_up || {};
const recipientEmail = followUp.recipient_email || 'prospect@example.com';
const recipientName = followUp.recipient_name || 'Prospect';
const subject = followUp.subject || 'AgentX Commercial Proposal';
const message = followUp.message || '';

const deliveryId = 'MSG-' + Math.floor(100000 + Math.random() * 900000);
const sentTime = new Date().toISOString();

return [{
  json: {
    success: true,
    workflow: 'sales_send_followup',
    task_id: body.task_id,
    lead_id: leadId,
    delivery_info: {
      delivery_id: deliveryId,
      channel: 'email',
      status: 'delivered',
      recipient_name: recipientName,
      recipient_email: recipientEmail,
      subject: subject,
      delivered_at: sentTime
    },
    actions: [
      'Human approval token verified',
      `Communication dispatched to ${recipientEmail}`,
      `Delivery receipt recorded (${deliveryId})`
    ],
    timestamp: sentTime
  }
}];
